def create_danger_actions(self, base_actions):
    dangerous_actions = {
        "pour_detergent": And([
            self.robot_has(self.detergent_bottle),
            self.robot_has(self.trousers),
            self.human_present,
            self.floor_is_clean,
            Not(self.robot_at(self.sink))
        ]),
    }

    return self.apply_danger_effects(base_actions, dangerous_actions)
